Q: How to query a custom element&#39;s internal elements while in the document from a DOMParser()? A: <p>I stripped your code to understand what you are trying to achieve.
I presume you want to load an external .mp3 file and control playing</p>
<p>I don't understand your <code>&lt;script&gt;</code> stuff.
And the use of HTML is overcomplicated.</p>
<p>Also ditched the <code>fetch</code> call because it is resticted by CORS settings,
when you use the native <code>&lt;audio src=&quot;...&quot;&gt;</code> attribute/property, there are no CORS restrictions.</p>
<p>Here is my take: <a href="https://jsfiddle.net/WebComponents/qnvct46z/" rel="nofollow noreferrer">https://jsfiddle.net/WebComponents/qnvct46z/</a></p>
<p>This (same code) StackOverflow Snippet blocks the <code>autoplay</code> attribute:
Run Snippet and press both Play buttons:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script&gt;
  // generic tag creation function
  const createElement = (tag, props = {}) =&gt; Object.assign(document.createElement(tag), props);
  // create &lt;audio-player&gt; Web Component
  customElements.define("audio-player", class extends HTMLElement {
    connectedCallback() {
      this.src = this.getAttribute("src") || "https://www.moviesoundclips.net/movies1/backtothefuture/style.mp3";
      this.append(
        this.audio = createElement("audio", {
          // set &lt;audio&gt; attributes and properties
          controls: !this.hasAttribute("nocontrols"),
          autoplay: this.hasAttribute("autoplay"),
          src: this.src,
          // easier native (oldskool) HTMLElement property events instead of (more complex) addEventListener
          onplay: (evt) =&gt; this.state(evt),
          onpause: (evt) =&gt; this.state(evt),
          onended: (evt) =&gt; this.state(evt)
        })
      );
    }
    state(evt) {
      console.log(evt.type,this.src);
      this[evt.type]?.(); // call method if it exist
    }
    play(){
      this.audio.play();
      this.setAttribute("playing", "");
    }
    pause(){
      this.audio.pause();
      this.removeAttribute("playing");
    }
    ended(){
      this.audio.pause();
      this.audio.currentTime = 0;
      this.removeAttribute("playing");
    }
  });
&lt;/script&gt;

&lt;audio-player autoplay src="https://cdn.jsdelivr.net/gh/rafaelreis-hotmart/Audio-Sample-files@master/sample.mp3"&gt;
&lt;/audio-player&gt;
&lt;audio-player&gt;&lt;/audio-player&gt;</code></pre>
</div>
</div>
</p>
<h2>PS</h2>
<p>The <code>connectedCallback</code> will run again if you move the Web Component in the DOM, so will create a duplicate  tag; check for <code>this.audio</code> before creating a new one... or delete the lightDOM... or use <code>.replaceWith()</code></p>
